'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isSameFloat32Array = require( '@stdlib/assert/is-same-float32array' );
var Float32Array = require( '@stdlib/array/float32' );
var sfillLessThan = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof sfillLessThan, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 6', function test( t ) {
	t.strictEqual( sfillLessThan.length, 6, 'has expected arity' );
	t.end();
});

tape( 'the function replaces strided array elements less than a provided search element', function test( t ) {
	var expected;
	var x;

	x = new Float32Array([
		0.0,
		2.0,
		0.0,
		4.0,
		-1.0,
		0.0,
		-5.0,
		6.0
	]);
	expected = new Float32Array([
		5.0,
		5.0,
		5.0,
		4.0,
		5.0,
		5.0,
		5.0,
		6.0
	]);

	sfillLessThan( x.length, 4.0, 5.0, x, 1, 0 );
	t.deepEqual( x, expected, 'returns expected value' );

	x = new Float32Array( [ 0.0, 2.0 ] );
	expected = new Float32Array( [ 5.0, 5.0 ] );

	sfillLessThan( x.length, 4.0, 5.0, x, 1, 0 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});

tape( 'if no elements are less than a provided search element, the function returns `x` unchanged', function test( t ) {
	var expected;
	var x;

	x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	expected = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	sfillLessThan( x.length, 1.0, 5.0, x, 1, 0 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});

tape( 'if provided a search element equal to `NaN`, the function returns `x` unchanged', function test( t ) {
	var x = new Float32Array( [ NaN, 1.0, NaN ] );

	sfillLessThan( x.length, NaN, 5.0, x, 1, 0 );
	t.ok( isnanf( x[ 0 ] ), 'returns expected value' );
	t.strictEqual( x[ 1 ], 1.0, 'returns expected value' );
	t.ok( isnanf( x[ 2 ] ), 'returns expected value' );

	t.end();
});

tape( 'the function does not replace `NaN` elements', function test( t ) {
	var expected;
	var x;

	x = new Float32Array( [ NaN, 1.0, NaN ] );
	expected = new Float32Array( [ NaN, 5.0, NaN ] );

	sfillLessThan( x.length, 4.0, 5.0, x, 1, 0 );
	t.strictEqual( isSameFloat32Array( x, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function considers `-0` and `+0` to be equal', function test( t ) {
	var expected;
	var x;

	x = new Float32Array( [ -0.0, 1.0, 0.0, -0.0 ] );
	expected = new Float32Array( [ -0.0, 1.0, 0.0, -0.0 ] );

	sfillLessThan( x.length, 0.0, 5.0, x, 1, 0 );
	t.strictEqual( isSameFloat32Array( x, expected ), true, 'returns expected value' );

	x = new Float32Array( [ -0.0, 1.0, 0.0, -0.0 ] );
	expected = new Float32Array( [ -0.0, 1.0, 0.0, -0.0 ] );

	sfillLessThan( x.length, -0.0, 5.0, x, 1, 0 );
	t.strictEqual( isSameFloat32Array( x, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns a reference to the input array', function test( t ) {
	var out;
	var x;

	x = new Float32Array( [ 1.0, 0.0, 3.0, 0.0, 5.0 ] );
	out = sfillLessThan( x.length, 4.0, 5.0, x, 1, 0 );

	t.strictEqual( out, x, 'same reference' );
	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function returns `x` unchanged', function test( t ) {
	var expected;
	var x;

	x = new Float32Array( [ 0.0, -4.0, 1.0 ] );
	expected = new Float32Array( [ 0.0, -4.0, 1.0 ] );

	sfillLessThan( 0, 4.0, 5.0, x, 1, 0 );
	t.deepEqual( x, expected, 'returns expected value' );

	x = new Float32Array( [ 0.0, -4.0, 1.0 ] );
	sfillLessThan( -4, 4.0, 5.0, x, 1, 0 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a stride', function test( t ) {
	var expected;
	var x;

	x = new Float32Array([
		0.0,  // 0
		-3.0,
		-5.0, // 1
		7.0,
		0.0   // 2
	]);
	expected = new Float32Array([
		5.0,  // 0
		-3.0,
		5.0,  // 1
		7.0,
		5.0   // 2
	]);

	sfillLessThan( 3, 4.0, 5.0, x, 2, 0 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a negative stride', function test( t ) {
	var expected;
	var x;

	x = new Float32Array([
		0.0,  // 2
		-3.0,
		-5.0, // 1
		7.0,
		0.0   // 0
	]);
	expected = new Float32Array([
		5.0,  // 2
		-3.0,
		5.0,  // 1
		7.0,
		5.0   // 0
	]);

	sfillLessThan( 3, 4.0, 5.0, x, -2, 4 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports an offset parameter', function test( t ) {
	var expected;
	var x;

	x = new Float32Array([
		1.0,
		0.0,  // 0
		3.0,
		0.0,  // 1
		4.0,
		6.0   // 2
	]);
	expected = new Float32Array([
		1.0,
		5.0,  // 0
		3.0,
		5.0,  // 1
		4.0,
		6.0   // 2
	]);

	sfillLessThan( 3, 4.0, 5.0, x, 2, 1 );
	t.deepEqual( x, expected, 'returns expected value' );

	x = new Float32Array([
		1.0,
		2.0,
		0.0,  // 0
		3.0,  // 1
		-4.0  // 2
	]);
	expected = new Float32Array([
		1.0,
		2.0,
		5.0,  // 0
		5.0,  // 1
		5.0   // 2
	]);

	sfillLessThan( 3, 4.0, 5.0, x, 1, 2 );
	t.deepEqual( x, expected, 'returns expected value' );

	t.end();
});
